def metric(data: pd.DataFrame) -> float:
    a_str = data['option_a_ratings'].apply(lambda x: ''.join([str(int(v)) for v in x]))

    m1 = a_str == '11000'
    m2 = a_str == '10100'
    m4 = a_str == '01111'
    m7 = a_str == '00111'

    def get_p_a(mask):
        subset = data.loc[mask, 'response']
        if len(subset) == 0:
            return 0.5
        return float((subset == 0).mean())

    p1 = get_p_a(m1)
    p2 = get_p_a(m2)
    p4 = get_p_a(m4)
    p7 = get_p_a(m7)

    return float((p4 - p7) + (p1 - p2))

